// web/data/*.json → web/data/bundle.js, so the page also works when opened as a file (browsers block fetch() on file://)
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, '../../web/data');
const read = (f) => (fs.existsSync(path.join(dir, f)) ? JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')) : null);
const data = { keeper: read('keeper.json'), cardano: read('cardano-run.json') };
fs.writeFileSync(path.join(dir, 'bundle.js'), `// generated by .github/scripts/data-bundle.cjs from data/*.json, used only when the page is opened from disk\nwindow.AG_DATA = ${JSON.stringify(data)};\n`);
console.log('bundle.js', Math.round(fs.statSync(path.join(dir, 'bundle.js')).size / 1024), 'KB');
